namespace Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\TenantConfigVersionVO;

trait TenantConfigVersionAccessor
{
    private ?TenantConfigVersionVO $_version = null;
    public function getVersion(): ?int
    {
        return $this->_version?->value();
    }
    public function version(): ?TenantConfigVersionVO
    {
        return $this->_version;
    }
    public function isVersionChanged(?self $original = null): bool
    {
        return null !== $this->_version && !$this->_version->equals($original?->_version);
    }
    public function withVersion(TenantConfigVersionVO|int|null $version): self
    {
        $copy = clone $this;
        $copy->_version = TenantConfigVersionVO::from($version);
        return $copy;
    }
}
